import { useState, useEffect } from 'react';

let renderCount = 0; // external mutation — bad

export default function StrictTest() {
  renderCount += 1; // BUG 1: side effect in render body
  const [tick, setTick] = useState(0);

  useEffect(() => {
    // BUG 2: no cleanup — will stack intervals in StrictMode
    setInterval(() => setTick(t => t + 1), 1000);
  }, []);

  return (
    <div>
      <p data-testid="tick">{tick}</p>
      <p>Render count: {renderCount}</p>
    </div>
  );
}
